package com.fullstack.exp92; import org.springframework.web.bind.annotation.*; import java.util.*; import java.util.concurrent.atomic.AtomicInteger; @RestController @RequestMapping("/api") @CrossOrigin(origins="http://localhost:3005") public class ReleaseController { AtomicInteger pct=new AtomicInteger(10),canary=new AtomicInteger(),stable=new AtomicInteger(); @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP");} @GetMapping("/release") public Map<String,Integer> release(){return Map.of("canaryPercent",pct.get(),"stablePercent",100-pct.get(),"canaryHits",canary.get(),"stableHits",stable.get());} @PostMapping("/canary/{p}") public Map<String,Integer> set(@PathVariable int p){if(p<0||p>100)throw new IllegalArgumentException("Use 0 to 100");pct.set(p);return release();} @PostMapping("/simulate/{n}") public Map<String,Integer> simulate(@PathVariable int n){if(n<1||n>1000)throw new IllegalArgumentException("Use 1 to 1000");for(int i=0;i<n;i++){if(i%100<pct.get())canary.incrementAndGet();else stable.incrementAndGet();}return release();} @PostMapping("/rollback") public Map<String,Integer> rollback(){pct.set(0);return release();} @PostMapping("/reset") public Map<String,Integer> reset(){pct.set(10);canary.set(0);stable.set(0);return release();} @GetMapping("/canary") public Map<String,String> canary(){return Map.of("release","Canary","version","2.0","status","Testing new version");} @GetMapping("/stable") public Map<String,String> stable(){return Map.of("release","Stable","version","1.0","status","Production");}}